<?php
namespace App\Http\Controllers; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth;
class AuthController extends Controller { public function create(){return view('auth.login');} public function store(Request $r){$credentials=$r->validate(['email'=>'required|email','password'=>'required']); if(!Auth::attempt($credentials,$r->boolean('remember'))) return back()->withErrors(['email'=>'The supplied credentials are invalid.'])->onlyInput('email'); $r->session()->regenerate(); return redirect()->intended(route('dashboard'));} public function destroy(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('login');} }
